        long seconds = baseTime / 1000;
        long fraction = ((baseTime % 1000) * 0x100000000L) / 1000;
        if (useBase1) {
            // set high-order bit if msb1baseTime 1900 used
            seconds |= 0x80000000L;
        }
        long time = seconds << 32 | fraction;
        return time;
    }

